#!/usr/bin/env bash
# deploy_logo_sticky_v2.sh — Sticky bar SADECE ucgen + "KRB Finans Kokpiti" (wordmark KALDIRILDI; ust nav zaten Derive Intelligence tasiyor).
#   STICKY_TOP_V1 korunur. HEM canli shells/kokpit.html HEM onizleme shells/kokpit2.html tam-degistirilir. build + force-recreate.
set -e
cd /opt/krb-assessment
TS=$(date +%s)
for F in shells/kokpit.html shells/kokpit2.html; do
  [ -f "$F" ] && cp "$F" "$F.bak.$TS" && echo "yedek: $F.bak.$TS"
done
printf '%s' '' | base64 -d > shells/kokpit.html
printf '%s' '' | base64 -d > shells/kokpit2.html
echo "yazildi: her iki shell ($(wc -c < shells/kokpit.html) bayt)"
grep -q 'url(#dtri)' shells/kokpit.html && echo "  ✓ ucgen logo mevcut" || { echo "HATA: logo yok"; exit 1; }
grep -q 'class=\"wm\">Derive' shells/kokpit.html && { echo "HATA: wordmark hala var"; exit 1; } || echo "  ✓ wordmark yok (sadece ucgen)"
grep -q 'STICKY_TOP_V1' shells/kokpit.html && echo "  ✓ sticky ust bar mevcut" || { echo "HATA: sticky yok"; exit 1; }
echo "=== docker build + recreate ==="
docker build -t krb-assessment:secure . >/tmp/build.log 2>&1 && echo "build ok" || { echo "BUILD HATASI:"; tail -20 /tmp/build.log; exit 1; }
docker compose up -d --force-recreate krb-assessment && echo "recreate ok"
echo "BITTI. Canli: /api/bi/kokpit  ·  Onizleme: /api/bi/kokpit2"
